    const modulus: u64 = 33554393;
    const multiplier: u64 = 252533;
    const first_code: u64 = 20151125;

    const answer = (first_code * modPow(multiplier, steps, modulus)) % modulus;
    try std.io.getStdOut().writer().print("{d}\n", .{answer});
